    this.cfg = c;
  }

  reset(): void {
    this.present = false;
    this.lastSeen = 0;
    this.pose = 'None';
    this.poseSince = 0;
    this.fired = false;
    this.needRelease = false;
    this.cooldownUntil = 0;
    this.armedUntil = 0;
    this.nextScroll = null;
    this.scrolled = false;
    this.lastAction = null;
    this.hint = null;
    this.lowSince = null;
    this.ema = null;
    this.buf = [];
  }

  update(frame: EngineFrame, now: number): GestureAction[] {
    const c = this.cfg;
    const out: GestureAction[] = [];
    const emit = (a: GestureAction) => {
      out.push(a);
      this.lastAction = { action: a, at: now };
    };

