import type { GestureConfig } from '@/contracts';

export const DEFAULT_GESTURE_CONFIG: GestureConfig = {
  minScore: 0.7, fistMinScore: 0.8, classifierScoreThreshold: 0.6,
  armHoldMs: 600, actionHoldMs: 800, armWindowMs: 5000, alwaysArmed: false,
  cooldownMs: 1200, releaseMs: 300,
  scrollFirstMs: 600, scrollRepeatMs: 700, scrollFraction: 0.4,
  swipeWindowMs: 400, swipeMinDx: 0.25, swipeDxToDyRatio: 2, swipeMinVelocity: 1.0,
  swipeNextDirection: 'left',
  minHandHeightFrac: 0.08, targetFps: 15, idleFps: 5, idleAfterMs: 10_000,
  delegate: 'GPU',
};

import type { CannedGesture, GestureAction, GestureConfig, GestureHud } from '@/contracts';

/** Minimal GestureRecognizerResult-like input. Landmarks are normalized, unmirrored camera coords. */
export type EngineFrame = {
  hand: null | {
    landmarks: Array<{ x: number; y: number }>;
    gesture: CannedGesture;
    score: number;
  };
};

type Snapshot = Omit<GestureHud, 'fps' | 'error'>;

const PALM = [0, 5, 9, 13, 17];
const DISCRETE: Partial<Record<CannedGesture, GestureAction>> = {
  Closed_Fist: 'TIMER_TOGGLE',
  Victory: 'SPEAK_TOGGLE',
};
const SCROLL: Partial<Record<CannedGesture, GestureAction>> = {
  Thumb_Up: 'SCROLL_UP',
  Thumb_Down: 'SCROLL_DOWN',
};
const EDGE = 0.01;
const MORE_LIGHT_MS = 3000;
const SCROLL_RELEASE_COOLDOWN_MS = 300;
const EMA_ALPHA = 0.5;

export class GestureEngine {
  private cfg: GestureConfig;
  private present = false;       // a valid hand was seen and not yet lost >= releaseMs
  private lastSeen = 0;
  private pose: CannedGesture = 'None';
  private poseSince = 0;
  private fired = false;         // one-shot latch per continuous pose hold (ARM or discrete action)
  private needRelease = false;   // discrete pose action fired; pose must change before re-arming
  private cooldownUntil = 0;
  private armedUntil = 0;        // 0 = not armed
  private nextScroll: number | null = null;
  private scrolled = false;
  private lastAction: Snapshot['lastAction'] = null;
  private hint: Snapshot['hint'] = null;
  private lowSince: number | null = null;
  private ema: { x: number; y: number } | null = null;
  private buf: Array<{ t: number; x: number; y: number; fist: boolean }> = [];

  constructor(config: GestureConfig) {
    this.cfg = config;
  }

  setConfig(c: GestureConfig): void {
    this.cfg = c;
  }

  reset(): void {
    this.present = false;
    this.lastSeen = 0;
    this.pose = 'None';
    this.poseSince = 0;
    this.fired = false;
    this.needRelease = false;
    this.cooldownUntil = 0;
    this.armedUntil = 0;
    this.nextScroll = null;
    this.scrolled = false;
    this.lastAction = null;
    this.hint = null;
    this.lowSince = null;
    this.ema = null;
    this.buf = [];
  }

  update(frame: EngineFrame, now: number): GestureAction[] {
    const c = this.cfg;
    const out: GestureAction[] = [];
    const emit = (a: GestureAction) => {
      out.push(a);
      this.lastAction = { action: a, at: now };
    };

    // Expiry. A hold already in progress is allowed to finish (it extends the window).
    if (!c.alwaysArmed && this.armedUntil > 0 && now > this.armedUntil && !this.isHolding(now)) {
      this.armedUntil = 0;
      emit('DISARM');
    }

    const h = frame.hand;
    let hint: Snapshot['hint'] = null;
    let valid = false;
    if (h) {
      const ys = h.landmarks.map((p) => p.y);
      const tall = Math.max(...ys) - Math.min(...ys) >= c.minHandHeightFrac;
      const edge = h.landmarks.some(
        (p) => p.x < EDGE || p.x > 1 - EDGE || p.y < EDGE || p.y > 1 - EDGE,
      );
      if (!tall) hint = 'move_closer';
      valid = tall && !edge;
    }

    if (!h || !valid) {
      this.lowSince = null;
      if (this.present && now - this.lastSeen >= c.releaseMs) this.lose(now);
      this.hint = hint;
      return out;
    }
    this.present = true;
    this.lastSeen = now;

    const low = h.score < c.minScore;
    this.lowSince = low ? (this.lowSince ?? now) : null;
    if (this.lowSince !== null && now - this.lowSince >= MORE_LIGHT_MS) hint = 'more_light';
    this.hint = hint;

    const pose: CannedGesture =
      low || (h.gesture === 'Closed_Fist' && h.score < c.fistMinScore) ? 'None' : h.gesture;
    if (pose !== this.pose) {
      if (this.scrolled) this.cooldownUntil = Math.max(this.cooldownUntil, now + SCROLL_RELEASE_COOLDOWN_MS);
      this.scrolled = false;
      this.nextScroll = null;
      this.needRelease = false;
      this.fired = false;
      this.pose = pose;
      this.poseSince = now;
    }

    // Palm centre, mirrored so directions match what the user sees, then EMA-smoothed.
    const sx = PALM.reduce((s, i) => s + h.landmarks[i].x, 0) / PALM.length;
    const sy = PALM.reduce((s, i) => s + h.landmarks[i].y, 0) / PALM.length;
    const mx = 1 - sx;
    this.ema = this.ema
      ? { x: EMA_ALPHA * mx + (1 - EMA_ALPHA) * this.ema.x, y: EMA_ALPHA * sy + (1 - EMA_ALPHA) * this.ema.y }
      : { x: mx, y: sy };

    if (!this.isArmed()) {
      this.buf.length = 0;
      if (pose === 'Open_Palm' && !this.fired && now - this.poseSince >= c.armHoldMs) {
        this.fired = true; // latch: palm held through a later expiry does not instantly re-arm
        this.armedUntil = now + c.armWindowMs;
        emit('ARM');
      }
      return out;
    }
    if (this.isCooling(now)) {
      this.buf.length = 0;
      return out;
    }

    // Hold timing starts when the cooldown ends, not when the pose began.
    const base = Math.max(this.poseSince, this.cooldownUntil);
    const discrete = DISCRETE[pose];
    const scroll = SCROLL[pose];
    let acted = false;
    if (discrete && !this.fired && now - base >= c.actionHoldMs) {
      this.fired = true;
      this.needRelease = true;
      this.cooldownUntil = now + c.cooldownMs;
      this.armedUntil = now + c.armWindowMs;
      this.buf.length = 0;
      emit(discrete);
      acted = true;
    } else if (scroll) {
      this.nextScroll ??= base + c.scrollFirstMs;
      if (now >= this.nextScroll) {
        this.nextScroll += c.scrollRepeatMs;
        if (this.nextScroll <= now) this.nextScroll = now + c.scrollRepeatMs;
        this.scrolled = true;
        this.armedUntil = now + c.armWindowMs;
        emit(scroll);
        acted = true;
      }
    }
    if (!acted) {
      const a = this.detectSwipe(now, pose === 'Closed_Fist');
      if (a) {
        this.cooldownUntil = now + c.cooldownMs;
        this.armedUntil = now + c.armWindowMs;
        emit(a);
      }
    }
    return out;
  }

  hud(now: number): Snapshot {
    const c = this.cfg;
    const armed = this.isArmed() && (this.present || !c.alwaysArmed);
    let state: Snapshot['state'];
    let holdProgress = 0;
    let pendingAction: GestureAction | null = null;
    const pose = this.pose;

    if (armed) {
      if (this.isCooling(now)) {
        state = 'cooldown';
      } else {
        state = 'armed';
        const base = Math.max(this.poseSince, this.cooldownUntil);
        const discrete = DISCRETE[pose];
        const scroll = SCROLL[pose];
        if (discrete) {
          state = 'holding';
          pendingAction = discrete;
          holdProgress = (now - base) / c.actionHoldMs;
        } else if (scroll) {
          state = 'holding';
          pendingAction = scroll;
          const next = this.nextScroll ?? base + c.scrollFirstMs;
          const period = this.nextScroll === null ? c.scrollFirstMs : c.scrollRepeatMs;
          holdProgress = 1 - (next - now) / period;
        }
      }
    } else {
      state = this.present ? 'hand_seen' : 'no_hand';
      if (this.present && pose === 'Open_Palm' && !this.fired) {
        pendingAction = 'ARM';
        holdProgress = (now - this.poseSince) / c.armHoldMs;
      }
    }
    return {
      state,
      pose,
      holdProgress: Math.min(1, Math.max(0, holdProgress)),
      pendingAction,
      armedRemainingMs: this.isArmed() && !c.alwaysArmed ? Math.max(0, this.armedUntil - now) : 0,
      lastAction: this.lastAction,
      hint: this.hint,
    };
  }

  private isArmed(): boolean {
    return this.cfg.alwaysArmed || this.armedUntil > 0;
  }

  private isCooling(now: number): boolean {
    return now < this.cooldownUntil || this.needRelease;
  }

  private isHolding(now: number): boolean {
    return this.present && (this.pose in DISCRETE || this.pose in SCROLL) && !this.isCooling(now);
  }

  private lose(now: number): void {
    if (this.scrolled) this.cooldownUntil = Math.max(this.cooldownUntil, now + SCROLL_RELEASE_COOLDOWN_MS);
    this.scrolled = false;
    this.nextScroll = null;
    this.present = false;
    this.needRelease = false;
    this.fired = false;
    this.pose = 'None';
    this.poseSince = now;
    this.buf = [];
    this.ema = null;
  }

  private detectSwipe(now: number, fist: boolean): GestureAction | null {
    const c = this.cfg;
    const b = this.buf;
    b.push({ t: now, x: this.ema!.x, y: this.ema!.y, fist });
    while (b[0].t < now - c.swipeWindowMs) b.shift();
    if (b.length < 2) return null;
    const first = b[0];
    const last = b[b.length - 1];
    const dx = last.x - first.x;
    const dy = last.y - first.y;
    if (Math.abs(dx) < c.swipeMinDx || Math.abs(dx) < c.swipeDxToDyRatio * Math.abs(dy)) return null;
    if (b.filter((p) => p.fist).length * 2 > b.length) return null;
    let peak = 0;
    for (let i = 1; i < b.length; i++) {
      const dt = b[i].t - b[i - 1].t;
      if (dt > 0) peak = Math.max(peak, (Math.sign(dx) * (b[i].x - b[i - 1].x) * 1000) / dt);
    }
    if (peak < c.swipeMinVelocity) return null;
    b.length = 0;
    return dx < 0 === (c.swipeNextDirection === 'left') ? 'NEXT_STEP' : 'PREV_STEP';
  }
}

import { describe, it, expect } from 'vitest';
import type { CannedGesture, GestureAction } from '@/contracts';
import { DEFAULT_GESTURE_CONFIG } from './config';
import { GestureEngine, type EngineFrame } from './engine';

const FRAME_MS = 1000 / 15;

type Seg = {
  ms: number;
  pose?: CannedGesture;
  score?: number;
  /** false = no hand in frame */
  hand?: boolean;
  /** palm centre in MIRRORED coords (what the user sees); defaults to previous position */
  x?: number;
  y?: number;
  toX?: number;
  toY?: number;
  /** hand bbox height, fraction of frame */
  size?: number;
};

function frame(pose: CannedGesture, score: number, mx: number, y: number, size: number): EngineFrame {
  const x = 1 - mx; // engine input is unmirrored
  const landmarks = Array.from({ length: 21 }, () => ({ x, y }));
  landmarks[12] = { x, y: y - size / 2 };
  landmarks[4] = { x, y: y + size / 2 };
  return { hand: { landmarks, gesture: pose, score } };
}

/** Feeds frames at 15 fps. A segment of `ms` covers frames at 0..ms inclusive (so 600 ms reaches t+600). */
class Rig {
  frameIdx = 0;
  mx = 0.5;
  y = 0.5;
  actions: Array<{ a: GestureAction; t: number }> = [];
  constructor(readonly engine: GestureEngine) {}

  get now() {
    return Math.round(this.frameIdx * FRAME_MS);
  }

  run(...segs: Seg[]) {
    for (const s of segs) {
      const n = Math.floor(s.ms / FRAME_MS + 1e-9) + 1;
      const x0 = s.x ?? this.mx;
      const y0 = s.y ?? this.y;
      const x1 = s.toX ?? x0;
      const y1 = s.toY ?? y0;
      for (let i = 0; i < n; i++) {
        const k = n > 1 ? i / (n - 1) : 1;
        this.mx = x0 + (x1 - x0) * k;
        this.y = y0 + (y1 - y0) * k;
        const t = this.now;
        const f: EngineFrame =
          s.hand === false
            ? { hand: null }
            : frame(s.pose ?? 'None', s.score ?? 0.95, this.mx, this.y, s.size ?? 0.3);
        for (const a of this.engine.update(f, t)) this.actions.push({ a, t });
        this.frameIdx++;
      }
    }
    return this;
  }

  of(a: GestureAction) {
    return this.actions.filter((x) => x.a === a);
  }
  names() {
    return this.actions.map((x) => x.a);
  }
}

const mk = (over: Partial<typeof DEFAULT_GESTURE_CONFIG> = {}) =>
  new Rig(new GestureEngine({ ...DEFAULT_GESTURE_CONFIG, ...over }));
const armed = (over: Partial<typeof DEFAULT_GESTURE_CONFIG> = {}) =>
  mk(over).run({ pose: 'Open_Palm', ms: 600 });

describe('arming', () => {
  it('palm held 600 ms emits exactly one ARM, even if held longer', () => {
    const r = mk().run({ pose: 'Open_Palm', ms: 600 });
    expect(r.names()).toEqual(['ARM']);
    r.run({ pose: 'Open_Palm', ms: 2000 });
    expect(r.names()).toEqual(['ARM']);
    expect(r.engine.hud(r.now).state).toBe('armed');
  });

  it('palm shorter than 600 ms does not arm; hud shows progress', () => {
    const r = mk().run({ pose: 'Open_Palm', ms: 400 });
    expect(r.actions).toEqual([]);
    const h = r.engine.hud(r.now - FRAME_MS);
    expect(h.state).toBe('hand_seen');
    expect(h.pendingAction).toBe('ARM');
    expect(h.holdProgress).toBeGreaterThan(0.5);
  });

  it('low-score palm does not arm', () => {
    const r = mk().run({ pose: 'Open_Palm', ms: 2000, score: 0.65 });
    expect(r.actions).toEqual([]);
  });

  it('expires after 5 s idle with one DISARM, and a still-held palm does not re-arm', () => {
    const r = armed().run({ pose: 'Open_Palm', ms: 5400 });
    expect(r.names()).toEqual(['ARM', 'DISARM']);
    const d = r.of('DISARM')[0].t;
    expect(d).toBeGreaterThan(5600);
    expect(d).toBeLessThan(5700);
    expect(r.engine.hud(r.now).state).toBe('hand_seen');
  });

  it('expiry with no hand goes to no_hand', () => {
    const r = armed().run({ hand: false, ms: 5400 });
    expect(r.names()).toEqual(['ARM', 'DISARM']);
    expect(r.engine.hud(r.now).state).toBe('no_hand');
  });

  it('a successful action extends the window by 5 s from the action time', () => {
    const r = armed().run({ pose: 'Open_Palm', ms: 4000 }, { pose: 'Closed_Fist', ms: 800 });
    const fire = r.of('TIMER_TOGGLE')[0].t;
    r.run({ pose: 'Open_Palm', ms: 4800 });
    expect(r.of('DISARM')).toHaveLength(0); // original window (5600) long gone
    r.run({ pose: 'Open_Palm', ms: 500 });
    const d = r.of('DISARM')[0].t;
    expect(d).toBeGreaterThan(fire + 5000);
    expect(d).toBeLessThan(fire + 5100);
  });

  it('alwaysArmed: fist fires without a palm and ARM/DISARM are never emitted', () => {
    const r = mk({ alwaysArmed: true }).run({ pose: 'Closed_Fist', ms: 800 }, { pose: 'None', ms: 8000 });
    expect(r.names()).toEqual(['TIMER_TOGGLE']);
  });
});

describe('discrete pose actions', () => {
  it('fist 800 ms -> exactly one TIMER_TOGGLE; 3 s more still one', () => {
    const r = armed().run({ pose: 'Closed_Fist', ms: 800 });
    expect(r.of('TIMER_TOGGLE')).toHaveLength(1);
    r.run({ pose: 'Closed_Fist', ms: 3000 });
    expect(r.of('TIMER_TOGGLE')).toHaveLength(1);
  });

  it('fist shorter than 800 ms does nothing', () => {
    const r = armed().run({ pose: 'Closed_Fist', ms: 700 }, { pose: 'Open_Palm', ms: 500 });
    expect(r.names()).toEqual(['ARM']);
  });

  it('release then fist again toggles a second time', () => {
    const r = armed().run(
      { pose: 'Closed_Fist', ms: 800 },
      { pose: 'Closed_Fist', ms: 3000 },
      { pose: 'Open_Palm', ms: 300 },
      { pose: 'Closed_Fist', ms: 800 },
    );
    expect(r.of('TIMER_TOGGLE')).toHaveLength(2);
  });

  it('a quick release does not beat the 1200 ms global cooldown', () => {
    const r = armed().run({ pose: 'Closed_Fist', ms: 800 });
    const first = r.of('TIMER_TOGGLE')[0].t;
    r.run({ pose: 'Open_Palm', ms: 100 }, { pose: 'Closed_Fist', ms: 3000 });
    const second = r.of('TIMER_TOGGLE')[1].t;
    expect(second).toBeGreaterThanOrEqual(first + 1200 + 800);
  });

  it('fist with score 0.75 (below fistMinScore) does nothing', () => {
    const r = armed().run({ pose: 'Closed_Fist', ms: 3000, score: 0.75 });
    expect(r.names()).toEqual(['ARM']);
  });

  it('victory 800 ms -> one SPEAK_TOGGLE, once per hold', () => {
    const r = armed().run({ pose: 'Victory', ms: 800 }, { pose: 'Victory', ms: 2000 });
    expect(r.of('SPEAK_TOGGLE')).toHaveLength(1);
  });

  it('hud reports holding progress and cooldown', () => {
    const r = armed().run({ pose: 'Closed_Fist', ms: 400 });
    let h = r.engine.hud(r.now - FRAME_MS);
    expect(h.state).toBe('holding');
    expect(h.pendingAction).toBe('TIMER_TOGGLE');
    expect(h.holdProgress).toBeGreaterThan(0.4);
    expect(h.holdProgress).toBeLessThan(0.7);
    r.run({ pose: 'Closed_Fist', ms: 500 });
    h = r.engine.hud(r.now - FRAME_MS);
    expect(h.state).toBe('cooldown');
    expect(h.lastAction?.action).toBe('TIMER_TOGGLE');
  });

  it('hand lost < 300 ms does not break a hold; >= 300 ms does', () => {
    const ok = armed().run(
      { pose: 'Closed_Fist', ms: 400 },
      { hand: false, ms: 200 },
      { pose: 'Closed_Fist', ms: 400 },
    );
    expect(ok.of('TIMER_TOGGLE')).toHaveLength(1);
    const broken = armed().run(
      { pose: 'Closed_Fist', ms: 400 },
      { hand: false, ms: 400 },
      { pose: 'Closed_Fist', ms: 400 },
    );
    expect(broken.of('TIMER_TOGGLE')).toHaveLength(0);
  });
});

describe('scroll', () => {
  it.each([
    ['Thumb_Up', 'SCROLL_UP'],
    ['Thumb_Down', 'SCROLL_DOWN'],
  ] as const)('%s held 2.1 s ticks at ~600, ~1300, ~2000 ms', (pose, action) => {
    const r = armed();
    const t0 = r.now;
    r.run({ pose, ms: 2100 });
    const ticks = r.of(action).map((x) => x.t - t0);
    expect(ticks).toHaveLength(3);
    [600, 1300, 2000].forEach((want, i) => expect(Math.abs(ticks[i] - want)).toBeLessThan(70));
    expect(r.names().filter((a) => a !== action)).toEqual(['ARM']);
  });

  it('scroll ticks extend the armed window; release after scrolling adds a 300 ms cooldown', () => {
    const r = armed().run({ pose: 'Thumb_Up', ms: 700 });
    expect(r.of('SCROLL_UP')).toHaveLength(1);
    r.run({ pose: 'Open_Palm', ms: 70 });
    expect(r.engine.hud(r.now - FRAME_MS).state).toBe('cooldown');
    r.run({ pose: 'Open_Palm', ms: 400 });
    expect(r.engine.hud(r.now - FRAME_MS).state).toBe('armed');
  });

  it('does not scroll while unarmed', () => {
    const r = mk().run({ pose: 'Thumb_Up', ms: 3000 });
    expect(r.actions).toEqual([]);
  });
});

describe('swipe', () => {
  const swipeLeft = { pose: 'Open_Palm', ms: 300, x: 0.8, toX: 0.2 } satisfies Seg;
  const swipeRight = { pose: 'Open_Palm', ms: 300, x: 0.2, toX: 0.8 } satisfies Seg;

  it('right->left (mirrored) while armed = exactly one NEXT_STEP; return stroke is ignored', () => {
    const r = armed().run({ pose: 'Open_Palm', ms: 300, x: 0.8 }, swipeLeft, { pose: 'Open_Palm', ms: 100 }, swipeRight);
    expect(r.of('NEXT_STEP')).toHaveLength(1);
    expect(r.of('PREV_STEP')).toHaveLength(0);
    r.run({ pose: 'Open_Palm', ms: 3000 });
    expect(r.names()).toEqual(['ARM', 'NEXT_STEP']);
  });

  it('left->right = PREV_STEP', () => {
    const r = armed().run({ pose: 'Open_Palm', ms: 300, x: 0.2 }, swipeRight);
    expect(r.names()).toEqual(['ARM', 'PREV_STEP']);
  });

  it("swipeNextDirection 'right' inverts", () => {
    const a = armed({ swipeNextDirection: 'right' }).run({ pose: 'Open_Palm', ms: 300, x: 0.2 }, swipeRight);
    expect(a.names()).toEqual(['ARM', 'NEXT_STEP']);
    const b = armed({ swipeNextDirection: 'right' }).run({ pose: 'Open_Palm', ms: 300, x: 0.8 }, swipeLeft);
    expect(b.names()).toEqual(['ARM', 'PREV_STEP']);
  });

  it('a second swipe after cooldown works', () => {
    const r = armed().run({ pose: 'Open_Palm', ms: 300, x: 0.8 }, swipeLeft, { pose: 'Open_Palm', ms: 1500, x: 0.8 }, swipeLeft);
    expect(r.of('NEXT_STEP')).toHaveLength(2);
  });

  it('slow drift is rejected (velocity), diagonal is rejected (dx/dy ratio), short is rejected (dx)', () => {
    const slow = armed().run({ pose: 'Open_Palm', ms: 300, x: 0.8 }, { pose: 'Open_Palm', ms: 2000, toX: 0.0 });
    const diag = armed().run({ pose: 'Open_Palm', ms: 300, x: 0.8, y: 0.2 }, { pose: 'Open_Palm', ms: 300, toX: 0.2, toY: 0.8 });
    const short = armed().run({ pose: 'Open_Palm', ms: 300, x: 0.6 }, { pose: 'Open_Palm', ms: 200, toX: 0.4 });
    for (const r of [slow, diag, short]) expect(r.names()).toEqual(['ARM']);
  });

  it('a fist stroke is not a swipe', () => {
    const r = armed().run({ pose: 'Closed_Fist', ms: 0, x: 0.8 }, { pose: 'Closed_Fist', ms: 300, x: 0.8, toX: 0.2 });
    expect(r.of('NEXT_STEP')).toHaveLength(0);
  });

